using System;
using FiresCore.Logging;
using UnityEngine;

namespace FiresDungeonMaster
{
    // FiresDungeonMaster's console banners, rendered through the shared Banner engine.
    //
    //   PrintBig()  → portcullis gate under torchlit battlements with the FIRES
    //                 DUNGEON MASTER brand. Fires at the very top of Setup as the
    //                 load announcement.
    //   Print()     → compact portcullis over a status frame ("GATES MANNED").
    //                 Fires once at first WorldStart.
    //
    // Art generated by Tools\gen_fires_banner.ps1 (spec: FiresDungeonMaster).
    // Color zones: battlements (Gray/DarkGray), torch glow (Yellow/DarkYellow),
    // portcullis bars (Gray/DarkGray), brand (White/Red), compact gate (DarkYellow).
    internal static class FiresDungeonMasterBanner
    {
        private static bool s_compactPrinted;

        public static void PrintBig()
        {
            try
            {
                EmitHeader("Fires Dungeon Master Loading...");
                Banner.Print(ToSegments(s_bigLines));
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresDungeonMaster] Big banner failed: {ex.Message}");
            }
        }

        public static void Print()
        {
            if (s_compactPrinted) return;
            s_compactPrinted = true;
            try
            {
                EmitHeader("Fires Dungeon Master Loaded.");
                Banner.Print(s_compactLines);
            }
            catch (Exception ex)
            {
                Debug.LogWarning($"[FiresDungeonMaster] Compact banner failed: {ex.Message}");
            }
        }

        // Routes the one-line header through the plugin's BepInEx log source (not
        // Debug.Log) so it prints once, colored by FiresLogColorPatch via the mod
        // source name, without a raw white stdout duplicate.
        private static void EmitHeader(string text)
        {
            if (FiresDungeonMasterPlugin.Log != null) FiresDungeonMasterPlugin.Log.LogInfo(text);
            else Debug.Log($"[FiresDungeonMaster] {text}");
        }

        private static Banner.Segment[][] ToSegments((string text, ConsoleColor color)[] lines)
        {
            var result = new Banner.Segment[lines.Length][];
            for (int i = 0; i < lines.Length; i++)
                result[i] = new[] { new Banner.Segment(lines[i].text, lines[i].color) };
            return result;
        }

        // Compact banner — portcullis gate over a status frame. 31-char frame body
        // (3 lead + ╔ + 26 ═ + ╗); 🏰 is a surrogate pair, but the console
        // ADVANCES ONE column for it (no VS16), however wide the font paints the glyph, so this row pads it as one cell.
        private static readonly Banner.Segment[][] s_compactLines =
        {
            new[] { new Banner.Segment("             ▄▀▀▀▀▀▀▀▄",      ConsoleColor.DarkGray) },
            new[]
